-- =====================================================================
-- Import de Clientes (legacy `clientesalbion`, 1327 filas) + sus
-- contactos (legacy: hasta 4 contactos fijos por cliente, 1363 en
-- total repartidos en 1004 clientes)
--
-- El nombre "clientesalbion" era historico (asi se llamaba la tabla en
-- la legacy), conceptualmente son los clientes de Albion -- se
-- importan a catalogo.clientes preservando el id legacy (idCliente),
-- mismo esquema que subcategorias/rubros/empresas en migraciones
-- previas.
--
-- Alcance "datos basicos" (decision del usuario): razon social, CUIT,
-- direccion, telefono/email principal, provincia/pais (resueltos desde
-- las tablas legacy `estados`/`paises` -- el codigo numerico se
-- tradujo a texto plano, no se creo una tabla de geografia nueva) y
-- rubro (texto libre tal cual venia -- 105/1327 tienen mas de un rubro
-- separados por coma, no se fuerza a elegir uno solo).
--
-- Contactos: se agrega catalogo.cliente_contactos (tabla aparte, no
-- 4 columnas fijas) con nombre/cargo/telefono/email + avatar_url para
-- cargar de ahora en mas -- la legacy no tenia foto por contacto, asi
-- que avatar_url viene NULL en todos.
--
-- Lo que NO se importa en esta pasada: lat/lng, imagen del cliente,
-- estado_cliente/estado_cotizacion.
--
-- creado_por: se resuelve el username legacy contra core.usuarios;
-- queda NULL cuando el usuario ya no existe en el sistema nuevo (ej.
-- "claudio_cortez", "aixa", "dimarcot", "juan", "edgardo", "danila").
-- creado_en: FechaAlta real de la legacy (nunca placeholder).
--
-- Se borra antes el cliente id=1 "de demo" (nota explicita "demo para
-- probar el dashboard") para liberar ese id -- cascada a la OF/OT de
-- demo que lo referenciaban, tambien de prueba.
-- =====================================================================

BEGIN;

ALTER TABLE catalogo.clientes
    ADD COLUMN IF NOT EXISTS cuit VARCHAR(30),
    ADD COLUMN IF NOT EXISTS direccion VARCHAR(255),
    ADD COLUMN IF NOT EXISTS telefono VARCHAR(60),
    ADD COLUMN IF NOT EXISTS email VARCHAR(255),
    ADD COLUMN IF NOT EXISTS provincia VARCHAR(100),
    ADD COLUMN IF NOT EXISTS pais VARCHAR(60),
    ADD COLUMN IF NOT EXISTS rubro VARCHAR(180),
    ADD COLUMN IF NOT EXISTS creado_por BIGINT REFERENCES core.usuarios(id),
    ADD COLUMN IF NOT EXISTS creado_en TIMESTAMPTZ NOT NULL DEFAULT now();

CREATE TABLE IF NOT EXISTS catalogo.cliente_contactos (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id BIGINT NOT NULL REFERENCES catalogo.clientes(id) ON DELETE CASCADE,
    nombre     VARCHAR(255),
    cargo      VARCHAR(60),
    telefono   VARCHAR(60),
    email      VARCHAR(255),
    avatar_url VARCHAR(255),
    orden      SMALLINT NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS idx_cliente_contactos_cliente ON catalogo.cliente_contactos(cliente_id);

DELETE FROM ingenieria.ordenes_trabajo WHERE of_id IN (SELECT id FROM ingenieria.ordenes_fabricacion WHERE cliente_id = 1);
DELETE FROM ingenieria.ordenes_fabricacion WHERE cliente_id = 1;
DELETE FROM catalogo.clientes WHERE id = 1;

